package exercise

func TopologicalOrder(n int, adj [][]int) []int {
	indegree := make([]int, n)
	for u := 0; u < n; u++ {
		for _, v := range adj[u] {
			indegree[v]++
		}
	}

	queue := make([]int, 0, n)
	for u := 0; u < n; u++ {
		if indegree[u] == 0 {
			queue = append(queue, u)
		}
	}

	order := make([]int, 0, n)
	for len(queue) > 0 {
		u := queue[0]
		queue = queue[1:]
		order = append(order, u)
		for _, v := range adj[u] {
			indegree[v]--
			if indegree[v] == 0 {
				queue = append(queue, v)
			}
		}
	}

	if len(order) != n {
		return []int{}
	}
	return order
}
